/// Ability is one ability a hero owns.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Ability {
    /// name is the ability's name, such as citadel_ability_hornet_snipe.
    pub name: String,
    /// slot is the ability's place on the hero: 0 to 3 are the ability keys.
    pub slot: i32,
    /// entity is the ability's entity handle, as DamageEvent.ability reports
    /// it.
    pub entity: u32,
    /// upgrades holds the bought tiers: bit 0 unlocks it and bits 1 to 3 are
    /// its upgrades.
    pub upgrades: u32,
    /// charges is the charges the ability holds.
    pub charges: i32,
    /// cooldown_end is the game time its cooldown ends, or zero without one.
    pub cooldown_end: f32,
    /// id identifies the ability's definition, as replays record it.
    pub id: u32,
    /// state is the packed upgrade word; its high half is upgrades.
    pub state: u32,
    /// cooldown_start is the game time its cooldown began.
    pub cooldown_start: f32,
    /// recharge_start is the game time its next charge began recovering.
    pub recharge_start: f32,
    /// recharge_end is the game time its next charge returns, or zero without
    /// one.
    pub recharge_end: f32,
    /// imbues names the abilities an imbuing item strengthens.
    pub imbues: Vec<String>,
}

impl Message for Ability {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.name.is_empty() {
            wire::string(out, 1, &self.name);
        }
        if self.slot != 0 {
            wire::int32(out, 2, self.slot);
        }
        if self.entity != 0 {
            wire::uint32(out, 3, self.entity);
        }
        if self.upgrades != 0 {
            wire::uint32(out, 4, self.upgrades);
        }
        if self.charges != 0 {
            wire::int32(out, 5, self.charges);
        }
        if self.cooldown_end != 0.0 {
            wire::float(out, 6, self.cooldown_end);
        }
        if self.id != 0 {
            wire::uint32(out, 7, self.id);
        }
        if self.state != 0 {
            wire::uint32(out, 8, self.state);
        }
        if self.cooldown_start != 0.0 {
            wire::float(out, 9, self.cooldown_start);
        }
        if self.recharge_start != 0.0 {
            wire::float(out, 10, self.recharge_start);
        }
        if self.recharge_end != 0.0 {
            wire::float(out, 11, self.recharge_end);
        }
        for v in &self.imbues {
            wire::string(out, 12, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.name = r.string(kind)?,
                2 => message.slot = r.int32(kind)?,
                3 => message.entity = r.uint32(kind)?,
                4 => message.upgrades = r.uint32(kind)?,
                5 => message.charges = r.int32(kind)?,
                6 => message.cooldown_end = r.float(kind)?,
                7 => message.id = r.uint32(kind)?,
                8 => message.state = r.uint32(kind)?,
                9 => message.cooldown_start = r.float(kind)?,
                10 => message.recharge_start = r.float(kind)?,
                11 => message.recharge_end = r.float(kind)?,
                12 => message.imbues.push(r.string(kind)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// AbilityOptions changes one ability of a player's hero.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct AbilityOptions {
    /// ability is the ability's name.
    pub ability: String,
    /// upgrades replaces the bought tiers, as ability.upgrades: 0b1111 unlocks
    /// it with all three upgrades.
    pub upgrades: Option<u32>,
    /// charges replaces the charges the ability holds, keeping its timers.
    pub charges: Option<i32>,
    /// cooldown_end replaces the game time its cooldown ends.
    pub cooldown_end: Option<f32>,
    /// recharge_end replaces the game time its next charge returns.
    pub recharge_end: Option<f32>,
    /// max_charges replaces the most charges the ability can hold, from 1 to 100;
    /// 0 returns it to the game's own. The server applies it, so the hero's
    /// screen can still show the game's maximum. charges above the new maximum
    /// are not removed; set them with charges.
    pub max_charges: Option<i32>,
    /// cooldown makes every cooldown the ability starts from now on last this
    /// many seconds, in place of the game's own length. An ability that holds
    /// charges waits this long between casts. 0 leaves the ability always
    /// ready, and a negative value returns it to the game's own. The game asks
    /// for the length as it starts each cooldown and applies the hero's cooldown
    /// reduction to it, so it holds for every later cast and the hero's screen
    /// shows it; a cooldown already running keeps its end, which cooldown_end
    /// moves. It holds for this ability of this hero until the mod stops, so
    /// set it again after a hero change or a replaced ability.
    pub cooldown: Option<f32>,
}

impl Message for AbilityOptions {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.ability.is_empty() {
            wire::string(out, 2, &self.ability);
        }
        if let Some(v) = self.upgrades {
            wire::uint32(out, 3, v);
        }
        if let Some(v) = self.charges {
            wire::int32(out, 4, v);
        }
        if let Some(v) = self.cooldown_end {
            wire::float(out, 5, v);
        }
        if let Some(v) = self.recharge_end {
            wire::float(out, 6, v);
        }
        if let Some(v) = self.max_charges {
            wire::int32(out, 7, v);
        }
        if let Some(v) = self.cooldown {
            wire::float(out, 8, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                2 => message.ability = r.string(kind)?,
                3 => message.upgrades = Some(r.uint32(kind)?),
                4 => message.charges = Some(r.int32(kind)?),
                5 => message.cooldown_end = Some(r.float(kind)?),
                6 => message.recharge_end = Some(r.float(kind)?),
                7 => message.max_charges = Some(r.int32(kind)?),
                8 => message.cooldown = Some(r.float(kind)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Modifier is one modifier an entity holds, as the game keeps it.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Modifier {
    /// name is the modifier's name, such as modifier_citadel_knockdown, as
    /// GiveModifier and ReadModifierField name it. It is empty when the game
    /// keeps no readable name.
    pub name: String,
    /// class_name is the modifier's server class, such as
    /// CCitadel_Modifier_Knockdown, which ReadModifierField takes. Several
    /// names can share a class.
    pub class_name: String,
    /// caster is the handle of the entity that applied it, such as the hero
    /// whose ability did, or 0 when none did.
    pub caster: u32,
    /// ability is the handle of the ability that applied it, or 0 when none did.
    pub ability: u32,
    /// age is how many seconds ago the game created it.
    pub age: f32,
    /// remaining is how many seconds it has left since it was last applied. It
    /// is absent for a modifier that lasts until something removes it.
    pub remaining: Option<f32>,
    /// stacks and max_stacks count its stacks, for a modifier that stacks.
    pub stacks: i32,
    pub max_stacks: i32,
    /// team is the team number it belongs to.
    pub team: u32,
    /// disabled is true while the game keeps it without its effects.
    pub disabled: bool,
}

impl Message for Modifier {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.name.is_empty() {
            wire::string(out, 1, &self.name);
        }
        if !self.class_name.is_empty() {
            wire::string(out, 2, &self.class_name);
        }
        if self.caster != 0 {
            wire::uint32(out, 3, self.caster);
        }
        if self.ability != 0 {
            wire::uint32(out, 4, self.ability);
        }
        if self.age != 0.0 {
            wire::float(out, 5, self.age);
        }
        if let Some(v) = self.remaining {
            wire::float(out, 6, v);
        }
        if self.stacks != 0 {
            wire::int32(out, 7, self.stacks);
        }
        if self.max_stacks != 0 {
            wire::int32(out, 8, self.max_stacks);
        }
        if self.team != 0 {
            wire::uint32(out, 9, self.team);
        }
        if self.disabled {
            wire::bool(out, 10, self.disabled);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.name = r.string(kind)?,
                2 => message.class_name = r.string(kind)?,
                3 => message.caster = r.uint32(kind)?,
                4 => message.ability = r.uint32(kind)?,
                5 => message.age = r.float(kind)?,
                6 => message.remaining = Some(r.float(kind)?),
                7 => message.stacks = r.int32(kind)?,
                8 => message.max_stacks = r.int32(kind)?,
                9 => message.team = r.uint32(kind)?,
                10 => message.disabled = r.bool(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// BuildCategory is one named group of a build's items.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BuildCategory {
    /// name is the category's title.
    pub name: String,
    /// description is the author's note on the category.
    pub description: String,
    /// items lists the category's items in buying order. An item this game
    /// version does not define is left out.
    pub items: Vec<BuildItem>,
}

impl Message for BuildCategory {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.name.is_empty() {
            wire::string(out, 1, &self.name);
        }
        if !self.description.is_empty() {
            wire::string(out, 2, &self.description);
        }
        for v in &self.items {
            wire::message(out, 3, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.name = r.string(kind)?,
                2 => message.description = r.string(kind)?,
                3 => message.items.push(BuildItem::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

