/// TraceOptions describes a line to test against the world. Layers are bits
/// of the game's collision layers: bit 0 is solid, 2 trigger, 4 player clip,
/// 18 player and 19 NPC.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct TraceOptions {
    /// start is where the line begins.
    pub start: Vector,
    /// end is where the line ends.
    pub end: Vector,
    /// layers selects what the line can hit; the default is solid and
    /// hitboxes.
    pub layers: Option<u64>,
    /// exclude removes things in these layers from the hits.
    pub exclude: Option<u64>,
    /// ignore lists entity handles the line passes through.
    pub ignore: Vec<u32>,
}

impl Message for TraceOptions {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.start != Vector::default() {
            wire::message(out, 1, &self.start);
        }
        if self.end != Vector::default() {
            wire::message(out, 2, &self.end);
        }
        if let Some(v) = self.layers {
            wire::uint64(out, 3, v);
        }
        if let Some(v) = self.exclude {
            wire::uint64(out, 4, v);
        }
        wire::packed(out, 5, &self.ignore, |out, v| wire::raw::uint32(out, *v));
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.start = Vector::decode(r.bytes(kind)?)?,
                2 => message.end = Vector::decode(r.bytes(kind)?)?,
                3 => message.layers = Some(r.uint64(kind)?),
                4 => message.exclude = Some(r.uint64(kind)?),
                5 => r.repeated(kind, wire::VARINT, &mut message.ignore, |r, kind| Ok(r.uint32(kind)?))?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

