/// HealEvent reports health an ability, item or lifesteal restored at once to
/// a hero or unit. Regeneration reports none, including what abilities such as
/// Siphon Life restore as regeneration, and neither do Modlock's own heal and
/// a heal at full health.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HealEvent {
    /// target is the entity healed.
    pub target: u32,
    /// target_player is the slot of the player whose hero was healed, or -1 for
    /// a unit.
    /// None stands for the schema's -1.
    pub target_player: Option<Player>,
    /// healer is the entity the heal came from, or zero when the game names
    /// none.
    pub healer: u32,
    /// healer_player is the slot of the player whose hero the healer is, or -1.
    /// None stands for the schema's -1.
    pub healer_player: Option<Player>,
    /// ability is the ability or item that healed, or zero.
    pub ability: u32,
    /// applied is the health the heal restored.
    pub applied: i32,
    /// requested is the heal's whole amount; it exceeds applied when the target
    /// reached full health.
    pub requested: i32,
}

impl Message for HealEvent {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.target != 0 {
            wire::uint32(out, 1, self.target);
        }
        match self.target_player {
            Some(v) if v.slot() == 0 => {}
            Some(v) => wire::int32(out, 2, v.slot()),
            None => wire::int32(out, 2, -1),
        }
        if self.healer != 0 {
            wire::uint32(out, 3, self.healer);
        }
        match self.healer_player {
            Some(v) if v.slot() == 0 => {}
            Some(v) => wire::int32(out, 4, v.slot()),
            None => wire::int32(out, 4, -1),
        }
        if self.ability != 0 {
            wire::uint32(out, 5, self.ability);
        }
        if self.applied != 0 {
            wire::int32(out, 6, self.applied);
        }
        if self.requested != 0 {
            wire::int32(out, 7, self.requested);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        message.target_player = Player::known(0);
        message.healer_player = Player::known(0);
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.target = r.uint32(kind)?,
                2 => message.target_player = Player::known(r.int32(kind)?),
                3 => message.healer = r.uint32(kind)?,
                4 => message.healer_player = Player::known(r.int32(kind)?),
                5 => message.ability = r.uint32(kind)?,
                6 => message.applied = r.int32(kind)?,
                7 => message.requested = r.int32(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

