/// FieldValue is one field's value. The host accepts any numeric case for a
/// numeric type and answers with the case its type reads as: a boolean, a
/// number for a type of 32 bits or less and a handle, an integer for a 64-bit
/// type, a vector or text.
#[derive(Clone, Debug, PartialEq)]
pub enum FieldValue {
    Boolean(bool),
    Number(f64),
    Integer(i64),
    Text(String),
    Vector(Vector),
}

impl FieldValue {
    /// encode appends the FieldValue to out.
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Boolean(v) => wire::bool(out, 1, *v),
            Self::Number(v) => wire::double(out, 2, *v),
            Self::Integer(v) => wire::int64(out, 3, *v),
            Self::Text(v) => wire::string(out, 4, v),
            Self::Vector(v) => wire::message(out, 5, v),
        }
    }

    /// decode returns the FieldValue in data, or None when data holds no case.
    pub fn decode(data: &[u8]) -> Result<Option<Self>, wire::Error> {
        let mut value = None;
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => value = Some(Self::Boolean(r.bool(kind)?)),
                2 => value = Some(Self::Number(r.double(kind)?)),
                3 => value = Some(Self::Integer(r.int64(kind)?)),
                4 => value = Some(Self::Text(r.string(kind)?)),
                5 => value = Some(Self::Vector(Vector::decode(r.bytes(kind)?)?)),
                _ => r.skip(kind)?,
            }
        }
        Ok(value)
    }
}

/// FieldWrite writes one schema field of an entity the host creates.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct FieldWrite {
    /// class_name is the server class that declares the field, or a subclass.
    pub class_name: String,
    /// field is the field's schema name, such as m_iLane. A dotted path, such as
    /// m_Collision.m_CollisionGroup, names a field inside an embedded structure.
    pub field: String,
    /// type is how to write the field.
    pub r#type: FieldType,
    /// value is the field's value.
    pub value: Option<FieldValue>,
}

impl Message for FieldWrite {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.class_name.is_empty() {
            wire::string(out, 1, &self.class_name);
        }
        if !self.field.is_empty() {
            wire::string(out, 2, &self.field);
        }
        if self.r#type as i32 != 0 {
            wire::int32(out, 3, self.r#type as i32);
        }
        if let Some(v) = &self.value {
            wire::nested(out, 4, |out| v.encode(out));
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.class_name = r.string(kind)?,
                2 => message.field = r.string(kind)?,
                3 => message.r#type = FieldType::from_i32(r.int32(kind)?),
                4 => message.value = FieldValue::decode(r.bytes(kind)?)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

