/// ControllerInfo describes one device a client reads.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ControllerInfo {
    /// id identifies the device within its stream for as long as it stays
    /// attached. A device plugged in again gets a new id.
    pub id: u32,
    /// name is the device's name, such as "Xbox Series X Controller".
    pub name: String,
    /// guid is SDL's joystick GUID in hexadecimal, which identifies the model
    /// and the way it is attached.
    pub guid: String,
    /// vendor and product are the USB vendor and product IDs, or zero when the
    /// device does not report them.
    pub vendor: u32,
    pub product: u32,
    /// axes, buttons and hats count the device's raw inputs, which State's
    /// lists follow.
    pub axes: u32,
    pub buttons: u32,
    pub hats: u32,
    /// gamepad is true when SDL knows the device's gamepad layout, so State
    /// carries the gamepad layer.
    pub gamepad: bool,
}

impl Message for ControllerInfo {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.id != 0 {
            wire::uint32(out, 1, self.id);
        }
        if !self.name.is_empty() {
            wire::string(out, 2, &self.name);
        }
        if !self.guid.is_empty() {
            wire::string(out, 3, &self.guid);
        }
        if self.vendor != 0 {
            wire::uint32(out, 4, self.vendor);
        }
        if self.product != 0 {
            wire::uint32(out, 5, self.product);
        }
        if self.axes != 0 {
            wire::uint32(out, 6, self.axes);
        }
        if self.buttons != 0 {
            wire::uint32(out, 7, self.buttons);
        }
        if self.hats != 0 {
            wire::uint32(out, 8, self.hats);
        }
        if self.gamepad {
            wire::bool(out, 9, self.gamepad);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.id = r.uint32(kind)?,
                2 => message.name = r.string(kind)?,
                3 => message.guid = r.string(kind)?,
                4 => message.vendor = r.uint32(kind)?,
                5 => message.product = r.uint32(kind)?,
                6 => message.axes = r.uint32(kind)?,
                7 => message.buttons = r.uint32(kind)?,
                8 => message.hats = r.uint32(kind)?,
                9 => message.gamepad = r.bool(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Gamepad is a device's gamepad layer, with named sticks, triggers and
/// buttons, for a device whose layout SDL knows.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Gamepad {
    /// left_x, left_y, right_x and right_y are the sticks, from -1 to 1, with x
    /// positive to the right and y positive down, as SDL reports them.
    pub left_x: f32,
    pub left_y: f32,
    pub right_x: f32,
    pub right_y: f32,
    /// left_trigger and right_trigger run from 0 at rest to 1 fully pulled.
    pub left_trigger: f32,
    pub right_trigger: f32,
    /// held lists the buttons held now.
    pub held: Vec<GamepadButton>,
    /// pressed and released list the buttons pressed and released since the
    /// previous state, once for each press, so a tap shorter than a server frame
    /// is listed in both.
    pub pressed: Vec<GamepadButton>,
    pub released: Vec<GamepadButton>,
}

impl Message for Gamepad {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.left_x != 0.0 {
            wire::float(out, 1, self.left_x);
        }
        if self.left_y != 0.0 {
            wire::float(out, 2, self.left_y);
        }
        if self.right_x != 0.0 {
            wire::float(out, 3, self.right_x);
        }
        if self.right_y != 0.0 {
            wire::float(out, 4, self.right_y);
        }
        if self.left_trigger != 0.0 {
            wire::float(out, 5, self.left_trigger);
        }
        if self.right_trigger != 0.0 {
            wire::float(out, 6, self.right_trigger);
        }
        wire::packed(out, 7, &self.held, |out, v| wire::raw::int32(out, *v as i32));
        wire::packed(out, 8, &self.pressed, |out, v| wire::raw::int32(out, *v as i32));
        wire::packed(out, 9, &self.released, |out, v| wire::raw::int32(out, *v as i32));
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.left_x = r.float(kind)?,
                2 => message.left_y = r.float(kind)?,
                3 => message.right_x = r.float(kind)?,
                4 => message.right_y = r.float(kind)?,
                5 => message.left_trigger = r.float(kind)?,
                6 => message.right_trigger = r.float(kind)?,
                7 => r.repeated(kind, wire::VARINT, &mut message.held, |r, kind| Ok(GamepadButton::from_i32(r.int32(kind)?)))?,
                8 => r.repeated(kind, wire::VARINT, &mut message.pressed, |r, kind| Ok(GamepadButton::from_i32(r.int32(kind)?)))?,
                9 => r.repeated(kind, wire::VARINT, &mut message.released, |r, kind| Ok(GamepadButton::from_i32(r.int32(kind)?)))?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// ControllerState is one device's inputs, the raw joystick layer always and
/// the gamepad layer when SDL knows the device.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ControllerState {
    /// id is the device's id in ControllerInfo.
    pub id: u32,
    /// axes holds each raw axis from -1 to 1, in the device's order. A radio
    /// transmitter's channels are its axes.
    pub axes: Vec<f32>,
    /// buttons holds whether each raw button is held, in the device's order.
    pub buttons: Vec<bool>,
    /// hats holds each hat's position as SDL's mask: 1 up, 2 right, 4 down and
    /// 8 left, combined on a diagonal, and 0 centered.
    pub hats: Vec<u32>,
    /// pressed and released list the raw buttons, by index, pressed and
    /// released since the previous state, once for each press.
    pub pressed: Vec<u32>,
    pub released: Vec<u32>,
    /// gamepad is the gamepad layer, when the device has one.
    pub gamepad: Gamepad,
}

impl Message for ControllerState {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.id != 0 {
            wire::uint32(out, 1, self.id);
        }
        wire::packed(out, 2, &self.axes, |out, v| wire::raw::float(out, *v));
        wire::packed(out, 3, &self.buttons, |out, v| wire::raw::bool(out, *v));
        wire::packed(out, 4, &self.hats, |out, v| wire::raw::uint32(out, *v));
        wire::packed(out, 5, &self.pressed, |out, v| wire::raw::uint32(out, *v));
        wire::packed(out, 6, &self.released, |out, v| wire::raw::uint32(out, *v));
        if self.gamepad != Gamepad::default() {
            wire::message(out, 7, &self.gamepad);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.id = r.uint32(kind)?,
                2 => r.repeated(kind, wire::FIXED32, &mut message.axes, |r, kind| Ok(r.float(kind)?))?,
                3 => r.repeated(kind, wire::VARINT, &mut message.buttons, |r, kind| Ok(r.bool(kind)?))?,
                4 => r.repeated(kind, wire::VARINT, &mut message.hats, |r, kind| Ok(r.uint32(kind)?))?,
                5 => r.repeated(kind, wire::VARINT, &mut message.pressed, |r, kind| Ok(r.uint32(kind)?))?,
                6 => r.repeated(kind, wire::VARINT, &mut message.released, |r, kind| Ok(r.uint32(kind)?))?,
                7 => message.gamepad = Gamepad::decode(r.bytes(kind)?)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Controller is one device as a mod reads it.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Controller {
    /// info describes the device.
    pub info: ControllerInfo,
    /// state is its inputs now, with the presses and releases since the mod's
    /// previous frame.
    pub state: ControllerState,
}

impl Message for Controller {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.info != ControllerInfo::default() {
            wire::message(out, 1, &self.info);
        }
        if self.state != ControllerState::default() {
            wire::message(out, 2, &self.state);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.info = ControllerInfo::decode(r.bytes(kind)?)?,
                2 => message.state = ControllerState::decode(r.bytes(kind)?)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// PlayerControllers is one watched player's controllers in a frame.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PlayerControllers {
    /// player is the player's slot.
    pub player: Player,
    /// stream is the state of the stream that brings them.
    pub stream: ControllerStream,
    /// controllers lists the player's devices, empty while stream is none.
    pub controllers: Vec<Controller>,
}

impl Message for PlayerControllers {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.player.slot() != 0 {
            wire::int32(out, 1, self.player.slot());
        }
        if self.stream as i32 != 0 {
            wire::int32(out, 2, self.stream as i32);
        }
        for v in &self.controllers {
            wire::message(out, 3, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.player = Player::of(r.int32(kind)?),
                2 => message.stream = ControllerStream::from_i32(r.int32(kind)?),
                3 => message.controllers.push(Controller::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// MovementSample is one watched hero's movement on one tick, as the game keeps
/// it. A hero whose position, velocity or ground the game does not provide has
/// no sample; another field the game did not provide is absent or zero.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MovementSample {
    /// player is the hero's player slot.
    pub player: Player,
    /// pawn is the hero's entity handle.
    pub pawn: u32,
    /// position is the hero's origin, at its feet.
    pub position: Vector,
    /// velocity is the hero's motion in units per second.
    pub velocity: Vector,
    /// grounded is true while the hero stands on something. sliding, mantling,
    /// climbing and dashing are the game's movement states.
    pub grounded: bool,
    pub sliding: bool,
    pub mantling: bool,
    pub climbing: bool,
    pub dashing: bool,
    /// jump_ability is the hero's jump ability, and wall_jumps the game's count of
    /// consecutive wall jumps on it.
    pub jump_ability: u32,
    pub wall_jumps: i32,
    /// mantle_ability is the hero's mantle ability, and mantle_start the game time
    /// its latest mantle began.
    pub mantle_ability: u32,
    pub mantle_start: f32,
    /// wall_contact is where the hero was when the jump ability last found a wall
    /// to jump off; it holds still once no wall qualifies.
    pub wall_contact: Vector,
    /// wall_normal is the last wall touched, never cleared.
    pub wall_normal: Vector,
    /// wall_jump_normal is the normal the latest wall jump used.
    pub wall_jump_normal: Vector,
    /// wall_jump_facing is the game's EWallJumpFacing, zero when not on a wall.
    pub wall_jump_facing: u32,
    /// zipline_time is the game time the hero last rode a zipline; it advances on
    /// every tick of a ride.
    pub zipline_time: Option<f32>,
    /// actions are the movement facts the game announced since the last tick.
    pub actions: Vec<MovementAction>,
    /// casts are the abilities the hero cast since the last tick, one per
    /// MOVEMENT_ACTION_ABILITY_EXECUTED, by entity handle as Ability.entity
    /// reports it; Abilities names each one's slot.
    pub casts: Vec<u32>,
    /// command is the movement the hero's player commanded since the last
    /// sample, absent before the game ran any of it.
    pub command: Option<MovementCommand>,
    /// interactions are the map objects the hero collected or broke since the
    /// last tick, as the game's own completion named the hero. A hero who stood
    /// by, or only benefited from another's pickup, has none.
    pub interactions: Vec<Interaction>,
}

impl Message for MovementSample {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.player.slot() != 0 {
            wire::int32(out, 1, self.player.slot());
        }
        if self.pawn != 0 {
            wire::uint32(out, 2, self.pawn);
        }
        if self.position != Vector::default() {
            wire::message(out, 3, &self.position);
        }
        if self.velocity != Vector::default() {
            wire::message(out, 4, &self.velocity);
        }
        if self.grounded {
            wire::bool(out, 6, self.grounded);
        }
        if self.sliding {
            wire::bool(out, 7, self.sliding);
        }
        if self.mantling {
            wire::bool(out, 8, self.mantling);
        }
        if self.climbing {
            wire::bool(out, 9, self.climbing);
        }
        if self.dashing {
            wire::bool(out, 10, self.dashing);
        }
        if self.jump_ability != 0 {
            wire::uint32(out, 11, self.jump_ability);
        }
        if self.wall_jumps != 0 {
            wire::int32(out, 12, self.wall_jumps);
        }
        if self.mantle_ability != 0 {
            wire::uint32(out, 13, self.mantle_ability);
        }
        if self.mantle_start != 0.0 {
            wire::float(out, 14, self.mantle_start);
        }
        if self.wall_contact != Vector::default() {
            wire::message(out, 15, &self.wall_contact);
        }
        if self.wall_normal != Vector::default() {
            wire::message(out, 16, &self.wall_normal);
        }
        if self.wall_jump_normal != Vector::default() {
            wire::message(out, 17, &self.wall_jump_normal);
        }
        if self.wall_jump_facing != 0 {
            wire::uint32(out, 18, self.wall_jump_facing);
        }
        if let Some(v) = self.zipline_time {
            wire::float(out, 19, v);
        }
        wire::packed(out, 20, &self.actions, |out, v| wire::raw::int32(out, *v as i32));
        wire::packed(out, 21, &self.casts, |out, v| wire::raw::uint32(out, *v));
        if let Some(v) = &self.command {
            wire::message(out, 22, v);
        }
        for v in &self.interactions {
            wire::message(out, 23, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.player = Player::of(r.int32(kind)?),
                2 => message.pawn = r.uint32(kind)?,
                3 => message.position = Vector::decode(r.bytes(kind)?)?,
                4 => message.velocity = Vector::decode(r.bytes(kind)?)?,
                6 => message.grounded = r.bool(kind)?,
                7 => message.sliding = r.bool(kind)?,
                8 => message.mantling = r.bool(kind)?,
                9 => message.climbing = r.bool(kind)?,
                10 => message.dashing = r.bool(kind)?,
                11 => message.jump_ability = r.uint32(kind)?,
                12 => message.wall_jumps = r.int32(kind)?,
                13 => message.mantle_ability = r.uint32(kind)?,
                14 => message.mantle_start = r.float(kind)?,
                15 => message.wall_contact = Vector::decode(r.bytes(kind)?)?,
                16 => message.wall_normal = Vector::decode(r.bytes(kind)?)?,
                17 => message.wall_jump_normal = Vector::decode(r.bytes(kind)?)?,
                18 => message.wall_jump_facing = r.uint32(kind)?,
                19 => message.zipline_time = Some(r.float(kind)?),
                20 => r.repeated(kind, wire::VARINT, &mut message.actions, |r, kind| Ok(MovementAction::from_i32(r.int32(kind)?)))?,
                21 => r.repeated(kind, wire::VARINT, &mut message.casts, |r, kind| Ok(r.uint32(kind)?))?,
                22 => message.command = Some(MovementCommand::decode(r.bytes(kind)?)?),
                23 => message.interactions.push(Interaction::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Interaction is one completed interaction with a map object.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Interaction {
    pub kind: InteractionKind,
    /// entity is the object's entity handle, which names it within this world
    /// only; origin and the names identify it across sessions.
    pub entity: u32,
    /// designer_name is the object's entity class, such as citadel_pickup_health,
    /// and subclass_id the hash of its subclass, such as the healing bat's
    /// citadel_pickup_health_float_in_world.
    pub designer_name: String,
    pub subclass_id: u32,
    /// origin is where the object stood before the interaction moved it: a
    /// vacuumed pickup's position as its vacuum began, otherwise its origin.
    pub origin: Vector,
    /// vacuum_start is the game time the pickup began flying to the hero, absent
    /// for a pickup collected on touch and for a prop. The interaction itself
    /// completed on the sample's tick.
    pub vacuum_start: Option<f32>,
    /// inflictor is the entity that broke a prop, such as the hero's projectile,
    /// or zero.
    pub inflictor: u32,
}

impl Message for Interaction {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.kind as i32 != 0 {
            wire::int32(out, 1, self.kind as i32);
        }
        if self.entity != 0 {
            wire::uint32(out, 2, self.entity);
        }
        if !self.designer_name.is_empty() {
            wire::string(out, 3, &self.designer_name);
        }
        if self.subclass_id != 0 {
            wire::uint32(out, 4, self.subclass_id);
        }
        if self.origin != Vector::default() {
            wire::message(out, 5, &self.origin);
        }
        if let Some(v) = self.vacuum_start {
            wire::float(out, 6, v);
        }
        if self.inflictor != 0 {
            wire::uint32(out, 7, self.inflictor);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.kind = InteractionKind::from_i32(r.int32(kind)?),
                2 => message.entity = r.uint32(kind)?,
                3 => message.designer_name = r.string(kind)?,
                4 => message.subclass_id = r.uint32(kind)?,
                5 => message.origin = Vector::decode(r.bytes(kind)?)?,
                6 => message.vacuum_start = Some(r.float(kind)?),
                7 => message.inflictor = r.uint32(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// MovementCommand is the movement a player commanded over one tick. The
/// server runs a player's commands as they arrive, so a tick may run several
/// or none: every press among them is kept once, and a tick that ran none
/// holds the last buttons without pressing them again.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MovementCommand {
    /// held, changed and scroll are the game's InButtonState masks as Buttons
    /// bits: the buttons down, the buttons that went down or up, and the
    /// presses of scroll-wheel buttons.
    pub held: u64,
    pub changed: u64,
    pub scroll: u64,
    /// forward, left and up are the movement axes, from -1 to 1.
    pub forward: f32,
    pub left: f32,
    pub up: f32,
    /// grounded is true when the hero stood on something as the tick began.
    pub grounded: bool,
}

impl Message for MovementCommand {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.held != 0 {
            wire::uint64(out, 1, self.held);
        }
        if self.changed != 0 {
            wire::uint64(out, 2, self.changed);
        }
        if self.scroll != 0 {
            wire::uint64(out, 3, self.scroll);
        }
        if self.forward != 0.0 {
            wire::float(out, 4, self.forward);
        }
        if self.left != 0.0 {
            wire::float(out, 5, self.left);
        }
        if self.up != 0.0 {
            wire::float(out, 6, self.up);
        }
        if self.grounded {
            wire::bool(out, 7, self.grounded);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.held = r.uint64(kind)?,
                2 => message.changed = r.uint64(kind)?,
                3 => message.scroll = r.uint64(kind)?,
                4 => message.forward = r.float(kind)?,
                5 => message.left = r.float(kind)?,
                6 => message.up = r.float(kind)?,
                7 => message.grounded = r.bool(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

