/// NpcOptions describes a unit that is not a player, such as a trooper.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct NpcOptions {
    /// class_name is the unit's entity class, such as npc_trooper or
    /// npc_trooper_boss.
    pub class_name: String,
    /// unit names the unit's game data entry, such as trooper_melee, or is empty
    /// for a unit that needs none.
    pub unit: String,
    /// team is the unit's team number; 4 is neutral.
    pub team: i32,
    /// position is the unit's origin, at its feet.
    pub position: Vector,
    /// facing is where the unit faces.
    pub facing: Option<Angles>,
    /// health is the unit's health; the default is the unit's own.
    pub health: Option<i32>,
    /// max_health is the unit's maximum health; the default is health.
    pub max_health: Option<i32>,
    /// lane is the lane the unit walks. A unit whose class walks none, unlike a
    /// trooper, refuses it.
    pub lane: Option<u32>,
    /// fields are schema fields the host writes after it creates the unit and
    /// before the unit spawns, such as m_iInitialTeamNum, which the game reads
    /// only while spawning. A write that fails cancels the spawn.
    pub fields: Vec<FieldWrite>,
}

impl Message for NpcOptions {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.class_name.is_empty() {
            wire::string(out, 1, &self.class_name);
        }
        if !self.unit.is_empty() {
            wire::string(out, 2, &self.unit);
        }
        if self.team != 0 {
            wire::int32(out, 3, self.team);
        }
        if self.position != Vector::default() {
            wire::message(out, 4, &self.position);
        }
        if let Some(v) = &self.facing {
            wire::message(out, 5, v);
        }
        if let Some(v) = self.health {
            wire::int32(out, 6, v);
        }
        if let Some(v) = self.max_health {
            wire::int32(out, 7, v);
        }
        if let Some(v) = self.lane {
            wire::uint32(out, 8, v);
        }
        for v in &self.fields {
            wire::message(out, 9, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.class_name = r.string(kind)?,
                2 => message.unit = r.string(kind)?,
                3 => message.team = r.int32(kind)?,
                4 => message.position = Vector::decode(r.bytes(kind)?)?,
                5 => message.facing = Some(Angles::decode(r.bytes(kind)?)?),
                6 => message.health = Some(r.int32(kind)?),
                7 => message.max_health = Some(r.int32(kind)?),
                8 => message.lane = Some(r.uint32(kind)?),
                9 => message.fields.push(FieldWrite::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

