/// Pawn is one player's pawn this frame: their hero, or the game's placeholder
/// before a hero is selected.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Pawn {
    /// entity is the pawn's entity handle, which ReadField reads. It changes
    /// whenever the game replaces the pawn.
    pub entity: u32,
    /// hero identifies the hero, as SelectHero returns it, or is 0 for a
    /// placeholder pawn that has none yet.
    pub hero: u32,
    /// team is the hero's team number.
    pub team: i32,
    /// health is the hero's health; zero or less is dead.
    pub health: i32,
    /// max_health is the hero's networked maximum health, which leaves out
    /// health from items until the hero respawns.
    pub max_health: i32,
    /// position is the hero's origin, at its feet.
    pub position: Vector,
    /// eye_angles is where the hero aims.
    pub eye_angles: Angles,
    /// camera_angles is where the player's camera looks.
    pub camera_angles: Angles,
    /// stamina is the hero's stamina, absent until it has spawned fully.
    pub stamina: Option<f32>,
    /// max_stamina is the hero's maximum stamina, present with stamina.
    pub max_stamina: Option<f32>,
    /// generation is the connection generation the hero belongs to.
    pub generation: u32,
    /// souls is the souls the player holds.
    pub souls: i32,
    /// eye_position is where the hero's view starts, for aiming traces.
    pub eye_position: Vector,
    /// velocity is the hero's motion in units per second.
    pub velocity: Vector,
    /// carrying_urn is whether the hero carries the soul urn, absent when the
    /// game's modifier states cannot be read.
    pub carrying_urn: Option<bool>,
    /// score is the player's scoreboard, absent when the game's scoreboard
    /// cannot be read.
    pub score: Option<Score>,
    /// camera_position is where the player's camera was in their latest command,
    /// shoulder offset included; a ray from it along camera_angles passes
    /// through the reticle. Absent for a bot and on hosts that cannot read
    /// commands.
    pub camera_position: Option<Vector>,
    /// effective_max_health is the maximum the hero's health bar shows, health
    /// from items included. Absent when the game's own reading is unavailable.
    pub effective_max_health: Option<i32>,
    /// ability_points is the ability points the player holds unspent.
    pub ability_points: i32,
    /// ability_unlocks is the ability unlocks the player holds unspent.
    pub ability_unlocks: i32,
}

impl Message for Pawn {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.entity != 0 {
            wire::uint32(out, 1, self.entity);
        }
        if self.hero != 0 {
            wire::uint32(out, 2, self.hero);
        }
        if self.team != 0 {
            wire::int32(out, 3, self.team);
        }
        if self.health != 0 {
            wire::int32(out, 4, self.health);
        }
        if self.max_health != 0 {
            wire::int32(out, 5, self.max_health);
        }
        if self.position != Vector::default() {
            wire::message(out, 6, &self.position);
        }
        if self.eye_angles != Angles::default() {
            wire::message(out, 7, &self.eye_angles);
        }
        if self.camera_angles != Angles::default() {
            wire::message(out, 8, &self.camera_angles);
        }
        if let Some(v) = self.stamina {
            wire::float(out, 9, v);
        }
        if let Some(v) = self.max_stamina {
            wire::float(out, 10, v);
        }
        if self.generation != 0 {
            wire::uint32(out, 11, self.generation);
        }
        if self.souls != 0 {
            wire::int32(out, 12, self.souls);
        }
        if self.eye_position != Vector::default() {
            wire::message(out, 13, &self.eye_position);
        }
        if self.velocity != Vector::default() {
            wire::message(out, 14, &self.velocity);
        }
        if let Some(v) = self.carrying_urn {
            wire::bool(out, 15, v);
        }
        if let Some(v) = &self.score {
            wire::message(out, 16, v);
        }
        if let Some(v) = &self.camera_position {
            wire::message(out, 17, v);
        }
        if let Some(v) = self.effective_max_health {
            wire::int32(out, 18, v);
        }
        if self.ability_points != 0 {
            wire::int32(out, 19, self.ability_points);
        }
        if self.ability_unlocks != 0 {
            wire::int32(out, 20, self.ability_unlocks);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.entity = r.uint32(kind)?,
                2 => message.hero = r.uint32(kind)?,
                3 => message.team = r.int32(kind)?,
                4 => message.health = r.int32(kind)?,
                5 => message.max_health = r.int32(kind)?,
                6 => message.position = Vector::decode(r.bytes(kind)?)?,
                7 => message.eye_angles = Angles::decode(r.bytes(kind)?)?,
                8 => message.camera_angles = Angles::decode(r.bytes(kind)?)?,
                9 => message.stamina = Some(r.float(kind)?),
                10 => message.max_stamina = Some(r.float(kind)?),
                11 => message.generation = r.uint32(kind)?,
                12 => message.souls = r.int32(kind)?,
                13 => message.eye_position = Vector::decode(r.bytes(kind)?)?,
                14 => message.velocity = Vector::decode(r.bytes(kind)?)?,
                15 => message.carrying_urn = Some(r.bool(kind)?),
                16 => message.score = Some(Score::decode(r.bytes(kind)?)?),
                17 => message.camera_position = Some(Vector::decode(r.bytes(kind)?)?),
                18 => message.effective_max_health = Some(r.int32(kind)?),
                19 => message.ability_points = r.int32(kind)?,
                20 => message.ability_unlocks = r.int32(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

