/// CameraValue is a value for a camera param: a number for every param but
/// the target, which takes a position.
#[derive(Clone, Debug, PartialEq)]
pub enum CameraValue {
    Number(f32),
    Position(Vector),
}

impl CameraValue {
    /// encode appends the CameraValue to out.
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Number(v) => wire::float(out, 1, *v),
            Self::Position(v) => wire::message(out, 2, v),
        }
    }

    /// decode returns the CameraValue in data, or None when data holds no case.
    pub fn decode(data: &[u8]) -> Result<Option<Self>, wire::Error> {
        let mut value = None;
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => value = Some(Self::Number(r.float(kind)?)),
                2 => value = Some(Self::Position(Vector::decode(r.bytes(kind)?)?)),
                _ => r.skip(kind)?,
            }
        }
        Ok(value)
    }
}

/// CameraMotion is how an operation moves its param.
#[derive(Clone, Debug, PartialEq)]
pub enum CameraMotion {
    /// Hold keeps the param where it is.
    Hold(CameraHold),
    /// Approach moves the param toward a value at a speed.
    Approach(CameraApproach),
    /// Spring pulls the param toward a value.
    Spring(CameraSpring),
    /// Lerp moves the param from one value to another over a time.
    Lerp(CameraLerp),
    /// Lag lets the param trail its usual value.
    Lag(CameraLag),
}

impl CameraMotion {
    /// encode appends the CameraMotion to out.
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Hold(v) => wire::message(out, 1, v),
            Self::Approach(v) => wire::message(out, 2, v),
            Self::Spring(v) => wire::message(out, 3, v),
            Self::Lerp(v) => wire::message(out, 4, v),
            Self::Lag(v) => wire::message(out, 5, v),
        }
    }

    /// decode returns the CameraMotion in data, or None when data holds no case.
    pub fn decode(data: &[u8]) -> Result<Option<Self>, wire::Error> {
        let mut value = None;
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => value = Some(Self::Hold(CameraHold::decode(r.bytes(kind)?)?)),
                2 => value = Some(Self::Approach(CameraApproach::decode(r.bytes(kind)?)?)),
                3 => value = Some(Self::Spring(CameraSpring::decode(r.bytes(kind)?)?)),
                4 => value = Some(Self::Lerp(CameraLerp::decode(r.bytes(kind)?)?)),
                5 => value = Some(Self::Lag(CameraLag::decode(r.bytes(kind)?)?)),
                _ => r.skip(kind)?,
            }
        }
        Ok(value)
    }
}

