/// CameraApproach moves a param toward a value.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CameraApproach {
    /// value is the value it approaches.
    pub value: Option<CameraValue>,
    /// speed is the most the param moves each second; omitted, 600.
    pub speed: Option<f32>,
    /// default_speed is the speed of the return to the usual value; omitted, 600.
    pub default_speed: Option<f32>,
    /// acceleration is how fast the speed builds each second; omitted, 1000.
    pub acceleration: Option<f32>,
    /// min_duration is the least time it runs, in seconds.
    pub min_duration: Option<f32>,
    /// chase_default approaches the param's usual value instead of value.
    pub chase_default: Option<bool>,
}

impl Message for CameraApproach {
    fn encode(&self, out: &mut Vec<u8>) {
        if let Some(v) = &self.value {
            wire::nested(out, 1, |out| v.encode(out));
        }
        if let Some(v) = self.speed {
            wire::float(out, 2, v);
        }
        if let Some(v) = self.default_speed {
            wire::float(out, 3, v);
        }
        if let Some(v) = self.acceleration {
            wire::float(out, 4, v);
        }
        if let Some(v) = self.min_duration {
            wire::float(out, 5, v);
        }
        if let Some(v) = self.chase_default {
            wire::bool(out, 6, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.value = CameraValue::decode(r.bytes(kind)?)?,
                2 => message.speed = Some(r.float(kind)?),
                3 => message.default_speed = Some(r.float(kind)?),
                4 => message.acceleration = Some(r.float(kind)?),
                5 => message.min_duration = Some(r.float(kind)?),
                6 => message.chase_default = Some(r.bool(kind)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

