/// CameraOptions adds one operation to a player's camera.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CameraOptions {
    /// context names a group of operations, which ClearCamera removes together.
    /// Operations on one param in one context run in order, each after the one
    /// before it ends, so a mod sends a whole sequence at once.
    pub context: Option<String>,
    /// param is the camera value the operation moves.
    pub param: CameraParam,
    /// motion is how it moves. Each motion ends once it reaches its value or
    /// its duration, and the param returns to its usual value unless another
    /// operation follows.
    pub motion: Option<CameraMotion>,
    /// delay starts the operation after this many seconds.
    pub delay: Option<f32>,
    /// relative adds the operation's values to the param's usual value instead
    /// of replacing it.
    pub relative: Option<bool>,
    /// priority decides between contexts moving one param: a higher operation
    /// takes over from a running lower one, which resumes when it ends, and a
    /// lower one does not show while a higher one runs. Omitted, 1.
    pub priority: Option<u32>,
    /// shared lets operations of other contexts move the param at the same time.
    pub shared: Option<bool>,
    /// target is the entity handle of the hero whose camera moves, as
    /// Pawn.entity reports it; omitted, the player's own hero.
    pub target: Option<u32>,
}

impl Message for CameraOptions {
    fn encode(&self, out: &mut Vec<u8>) {
        if let Some(v) = &self.context {
            wire::string(out, 2, v);
        }
        if self.param as i32 != 0 {
            wire::int32(out, 3, self.param as i32);
        }
        if let Some(v) = &self.motion {
            wire::nested(out, 4, |out| v.encode(out));
        }
        if let Some(v) = self.delay {
            wire::float(out, 5, v);
        }
        if let Some(v) = self.relative {
            wire::bool(out, 6, v);
        }
        if let Some(v) = self.priority {
            wire::uint32(out, 7, v);
        }
        if let Some(v) = self.shared {
            wire::bool(out, 8, v);
        }
        if let Some(v) = self.target {
            wire::uint32(out, 9, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                2 => message.context = Some(r.string(kind)?),
                3 => message.param = CameraParam::from_i32(r.int32(kind)?),
                4 => message.motion = CameraMotion::decode(r.bytes(kind)?)?,
                5 => message.delay = Some(r.float(kind)?),
                6 => message.relative = Some(r.bool(kind)?),
                7 => message.priority = Some(r.uint32(kind)?),
                8 => message.shared = Some(r.bool(kind)?),
                9 => message.target = Some(r.uint32(kind)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// HeroTarget is the state RestoreHero gives one hero. Omitted parts keep the
/// hero's own.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HeroTarget {
    /// position is the hero's origin.
    pub position: Vector,
    /// facing is where the camera faces; a bot's hero faces it.
    pub facing: Angles,
    /// fresh gives full health and stamina and readies every ability, in place
    /// of health, max health, upgrade bonuses and timers. A bot's ability
    /// upgrades may grow while the restore runs.
    pub fresh: Option<bool>,
    /// level sets the hero's level, and its souls to what that level needs. The
    /// game raises a level once the hero's souls pass the next one and never
    /// lowers one, so a level held with other souls would change within a
    /// second. A hero with more souls than the level's band loses them, from its
    /// wallet first; one with fewer gains wallet souls. A hero whose souls
    /// already fit the level keeps them, and the restore fails if they cannot be
    /// moved there.
    pub level: Option<i32>,
    /// health and max_health set the hero's health and its base maximum. Both
    /// are required unless the target is fresh.
    pub health: Option<i32>,
    pub max_health: Option<i32>,
    /// upgrade_bonuses are the three stat bonuses purchases add, as replays
    /// record them.
    pub upgrade_bonuses: Vec<f32>,
    /// abilities sets the hero's abilities in their slots.
    pub abilities: Vec<EquipmentTarget>,
    /// items lists the items that replace the hero's when replace_items is set.
    pub items: Vec<EquipmentTarget>,
    /// replace_items replaces every item the hero owns with items; an empty list
    /// removes them.
    pub replace_items: Option<bool>,
    /// timers sets the charges and cooldowns of owned abilities and items.
    pub timers: Vec<TimerTarget>,
}

impl Message for HeroTarget {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.position != Vector::default() {
            wire::message(out, 1, &self.position);
        }
        if self.facing != Angles::default() {
            wire::message(out, 2, &self.facing);
        }
        if let Some(v) = self.fresh {
            wire::bool(out, 3, v);
        }
        if let Some(v) = self.level {
            wire::int32(out, 4, v);
        }
        if let Some(v) = self.health {
            wire::int32(out, 5, v);
        }
        if let Some(v) = self.max_health {
            wire::int32(out, 6, v);
        }
        wire::packed(out, 7, &self.upgrade_bonuses, |out, v| wire::raw::float(out, *v));
        for v in &self.abilities {
            wire::message(out, 8, v);
        }
        for v in &self.items {
            wire::message(out, 9, v);
        }
        if let Some(v) = self.replace_items {
            wire::bool(out, 10, v);
        }
        for v in &self.timers {
            wire::message(out, 11, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.position = Vector::decode(r.bytes(kind)?)?,
                2 => message.facing = Angles::decode(r.bytes(kind)?)?,
                3 => message.fresh = Some(r.bool(kind)?),
                4 => message.level = Some(r.int32(kind)?),
                5 => message.health = Some(r.int32(kind)?),
                6 => message.max_health = Some(r.int32(kind)?),
                7 => r.repeated(kind, wire::FIXED32, &mut message.upgrade_bonuses, |r, kind| Ok(r.float(kind)?))?,
                8 => message.abilities.push(EquipmentTarget::decode(r.bytes(kind)?)?),
                9 => message.items.push(EquipmentTarget::decode(r.bytes(kind)?)?),
                10 => message.replace_items = Some(r.bool(kind)?),
                11 => message.timers.push(TimerTarget::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// EquipmentTarget is one ability or item a HeroTarget gives the hero.
