pub struct BotOptions {
    /// name is the bot's player name.
    pub name: String,
    /// team is the team number to join: 2 or 3.
    pub team: i32,
    /// hero names the bot's hero, such as hero_wraith, or gives its identifier
    /// as Pawn.hero reports it.
    pub hero: Option<BotOptionsHero>,
    /// position is where the bot appears.
    pub position: Option<Vector>,
}

/// BotOptionsHero is the hero of a BotOptions.
#[derive(Clone, Debug, PartialEq)]
pub enum BotOptionsHero {
    HeroName(String),
    HeroId(u32),
}

impl Message for BotOptions {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.name.is_empty() {
            wire::string(out, 1, &self.name);
        }
        if self.team != 0 {
            wire::int32(out, 2, self.team);
        }
        match &self.hero {
            Some(BotOptionsHero::HeroName(v)) => wire::string(out, 3, hero_name(v)),
            Some(BotOptionsHero::HeroId(v)) => wire::uint32(out, 4, *v),
            None => {}
        }
        if let Some(v) = &self.position {
            wire::message(out, 5, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.name = r.string(kind)?,
                2 => message.team = r.int32(kind)?,
                3 => message.hero = Some(BotOptionsHero::HeroName(r.string(kind)?)),
                4 => message.hero = Some(BotOptionsHero::HeroId(r.uint32(kind)?)),
                5 => message.position = Some(Vector::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

