/// Node is one panel in a tree. The root's id is empty; it is a full-screen
/// panel that lets clicks through to the game.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Node {
    /// id names the node within its tree.
    pub id: String,
    /// kind selects the panel the node draws.
    pub kind: Kind,
    /// children lists the ids of the node's children in drawing order. A node
    /// that no parent lists is not drawn.
    pub children: Vec<String>,
    /// text is a label's words.
    pub text: String,
    /// image is an image's path in the game's content, such as
    /// "file://{images}/heroes/wraith_card.psd". The renderer writes the name of
    /// the mod's content addon in place of "{addon}", so a mod names its own
    /// pictures as "file://{images}/{addon}/mark.png" without knowing the name
    /// the host mounted them under; a renderer that knows no addon for the mod
    /// draws the image empty.
    pub image: String,
    /// style lays out and paints the node.
    pub style: Style,
    /// layout is a layout's path within the mod's content addon, such as
    /// "inventory.xml": one or more segments of letters, digits, '_', '-' and
    /// '.', none of them "..", ending in ".xml".
    pub layout: String,
    /// data is the JSON value a layout's script reads, or a route's value. The
    /// renderer sets a layout's data as the modlock_data attribute of its panel
    /// before loading the layout, and each route as the attribute
    /// modlock_route_<route> of every layout of the mod. After a draw that
    /// changes any of them it plays the sound event "modlock_data_changed",
    /// which no sound has, so a script that registers for the unhandled
    /// PlaySoundEffect event hears it and reads its attributes again. The
    /// Panorama library scripts/modlock/layout.js does both for a layout.
    pub data: String,
    /// hide_hud lists the parts of the game's own HUD the renderer hides while
    /// the root holds them; only the root's list counts. A part shows again once
    /// no mod's root lists it, so a mod that stops, a reset and a player who
    /// leaves all bring it back.
    pub hide_hud: Vec<HudPart>,
    /// route names a route node's data route: one or more letters, digits, '_',
    /// '-' and '.'.
    pub route: String,
    /// hover is the style drawn over the node's style while the pointer is over
    /// it. Each property it sets returns to the node's own value, or to the
    /// property's resting value, when the pointer leaves. A node with a hover
    /// style takes the pointer, so the game behind it does not.
    pub hover: Option<Box<Style>>,
    /// tooltip is the text the game's tooltip shows while the pointer is over the
    /// node. A node with a tooltip takes the pointer.
    pub tooltip: String,
    /// item is an item's id, the game's string token of its class name, whose
    /// shop card the game shows while the pointer is over the node, in place of
    /// the tooltip. A node with an item takes the pointer.
    pub item: u32,
    /// ability is an ability's id, the game's string token of its class name as
    /// item's is, whose window the game shows while the pointer is over the
    /// node, in place of the tooltip and the shop card, in the player's
    /// language. A node with an ability takes the pointer.
    pub ability: u32,
    /// ability_player is the player slot whose hero the ability's window reads
    /// its numbers from; that hero must stand on the map.
    pub ability_player: u32,
    /// sound is the game's sound event a button plays when pressed, such as
    /// "UI.MainMenu.Activate": one or more letters, digits, '_', '-' and '.'.
    pub sound: String,
    /// hover_sound is the game's sound event played as the pointer enters the
    /// node, named as sound is.
    pub hover_sound: String,
    /// disabled keeps a button from taking presses; its style shows why.
    pub disabled: bool,
    /// scaling fits an image or a hero's portrait into the node's box.
    pub scaling: Scaling,
    /// hero is a hero image's hero, by the game's hero id.
    pub hero: i32,
    /// hero_look picks which of the game's pictures of the hero a hero image
    /// draws.
    pub hero_look: HeroLook,
    /// input is the control an input node draws and the value it holds. Each
    /// change the player makes reaches the mod as a UiInputEvent, which the host
    /// checks against the control: a slider's range and step, a dropdown's
    /// options, an entry's length. The renderer keeps the player's own edit
    /// until a draw changes the value the node holds, so the mod's value is the
    /// truth and a redraw for another reason does not undo a change in flight.
    pub input: Option<NodeInput>,
    /// token draws a label in the player's language: a token of the game's
    /// localization, such as "#Citadel_HeroName_Haze", shown in place of text.
    /// It is '#' then one or more letters, digits, '_', '-' and '.'.
    pub token: String,
    /// variables fill the {s:name} places in a localized label's token.
    pub variables: Vec<NodeVariablesEntry>,
    /// steam_id is an avatar's player, by Steam id.
    pub steam_id: u64,
    /// enter is the style a node's new panel starts from. The node's transition
    /// eases it from there to the node's style, so it fades, slides or grows
    /// in.
    pub enter: Option<Box<Style>>,
    /// exit is the style a node's panel eases to, over its transition, when the
    /// node leaves the tree; the panel goes once the transition ends.
    pub exit: Option<Box<Style>>,
    /// cycle repeats a change to the node's style while it shows, such as a
    /// pulse or a blink.
    pub cycle: Option<Box<Cycle>>,
    /// classes names the node's classes, which the mod's style sheets select.
    /// The renderer adds and removes only the classes that changed, so a change
    /// starts the sheets' transitions. The node's style still wins over a class.
    pub classes: Vec<String>,
    /// sheets lists the mod's style sheets by their paths in its content addon's
    /// styles directory, such as "hud.css"; only the root's list counts. Each
    /// sheet styles the mod's panels and no other mod's, and a later sheet wins
    /// over an earlier one. The renderer loads a sheet as the layout that the
    /// build writes beside it, named for the sheet with ".xml" added, such as
    /// "hud.css.xml", so a sheet loads only where the mod's layouts do. A path is
    /// one or more segments of letters, digits, '_', '-' and '.', none of them
    /// "..", ending in ".css".
    pub sheets: Vec<String>,
    /// free_cursor shows the player's mouse cursor without Tab held, so they can
    /// click the mod's panels, while the root holds it; only the root's value
    /// counts. Aiming returns once no mod's root frees the cursor, so a mod that
    /// stops, a reset and a player who leaves all give the mouse back.
    pub free_cursor: bool,
    /// free_cursor_asks counts the mod's explicit asks for the cursor. The player
    /// can put the cursor away with the game's own keys, and that choice holds
    /// until the count rises: a rise shows the cursor again while the root frees
    /// it, and a screen that changes anything else leaves the player's choice be.
    pub free_cursor_asks: u32,
    /// cues are sounds the player's game plays for them alone, each once; only
    /// the root's list counts. The renderer plays each cue numbered above the
    /// newest it has played for the mod, notes the list it first sees without
    /// playing it, so a reloaded renderer plays nothing old, and plays a new UI
    /// lifetime's list from its start. The list keeps only the last few cues.
    pub cues: Vec<Cue>,
    /// ability_bar_presses asks for clicks on the game's own ability bar: a click
    /// on the icon or the upgrade pips of the ability in slot N, 0 to 3, reaches
    /// the mod as a press of the node "ability:N", which no element's id can be.
    /// The renderer's stock guard sends one press per click while it may hold
    /// the game's HUD, so a handler left by an ended session sends nothing. Only
    /// the root's flag counts.
    pub ability_bar_presses: bool,
    /// ability_display shows abilities in place of the ones the game shows for a
    /// player's hero: on that player's row of the game's Tab screen, and for the
    /// row marked own, on the player's own ability bar too. The game draws those
    /// from the hero's standard abilities by slot, so an ability the mod gave
    /// with replaceAbility shows as the one it replaced. The renderer's stock
    /// guard draws them in the game's own frame, ring and pips, opens the game's
    /// ability window for them, and gives the game's own back once the screen
    /// stops asking or it may no longer hold the HUD. Only the root's rows count.
    pub ability_display: Vec<AbilityRow>,
    /// clock runs a label's time in the player's game, so the tree stays the
    /// same while the time changes. The label shows the time in place of its
    /// text, or fills its token's {s:clock} place with it.
    pub clock: Option<Clock>,
    /// hide_in_chat hides the node while the player has the game's chat box open,
    /// which then shows the chat history itself, so a node that repeats chat,
    /// such as a lane of chat lines, gives way to it. The renderer reads the
    /// chat box's state in the player's game; a renderer that finds no chat box
    /// always shows the node.
    pub hide_in_chat: bool,
}

/// NodeInput is the input of a Node.
#[derive(Clone, Debug, PartialEq)]
pub enum NodeInput {
    TextEntry(TextEntry),
    Slider(Slider),
    Toggle(Toggle),
    Dropdown(Dropdown),
}

impl Message for Node {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.id.is_empty() {
            wire::string(out, 1, &self.id);
        }
        if self.kind as i32 != 0 {
            wire::int32(out, 2, self.kind as i32);
        }
        for v in &self.children {
            wire::string(out, 3, v);
        }
        if !self.text.is_empty() {
            wire::string(out, 4, &self.text);
        }
        if !self.image.is_empty() {
            wire::string(out, 5, &self.image);
        }
        if self.style != Style::default() {
            wire::message(out, 6, &self.style);
        }
        if !self.layout.is_empty() {
            wire::string(out, 7, &self.layout);
        }
        if !self.data.is_empty() {
            wire::string(out, 8, &self.data);
        }
        wire::packed(out, 9, &self.hide_hud, |out, v| wire::raw::int32(out, *v as i32));
        if !self.route.is_empty() {
            wire::string(out, 10, &self.route);
        }
        if let Some(v) = &self.hover {
            wire::message(out, 11, &**v);
        }
        if !self.tooltip.is_empty() {
            wire::string(out, 12, &self.tooltip);
        }
        if self.item != 0 {
            wire::uint32(out, 32, self.item);
        }
        if self.ability != 0 {
            wire::uint32(out, 34, self.ability);
        }
        if self.ability_player != 0 {
            wire::uint32(out, 35, self.ability_player);
        }
        if !self.sound.is_empty() {
            wire::string(out, 13, &self.sound);
        }
        if !self.hover_sound.is_empty() {
            wire::string(out, 14, &self.hover_sound);
        }
        if self.disabled {
            wire::bool(out, 15, self.disabled);
        }
        if self.scaling as i32 != 0 {
            wire::int32(out, 16, self.scaling as i32);
        }
        if self.hero != 0 {
            wire::int32(out, 17, self.hero);
        }
        if self.hero_look as i32 != 0 {
            wire::int32(out, 18, self.hero_look as i32);
        }
        match &self.input {
            Some(NodeInput::TextEntry(v)) => wire::message(out, 19, v),
            Some(NodeInput::Slider(v)) => wire::message(out, 20, v),
            Some(NodeInput::Toggle(v)) => wire::message(out, 21, v),
            Some(NodeInput::Dropdown(v)) => wire::message(out, 22, v),
            None => {}
        }
        if !self.token.is_empty() {
            wire::string(out, 23, &self.token);
        }
        for v in &self.variables {
            wire::message(out, 24, v);
        }
        if self.steam_id != 0 {
            wire::fixed64(out, 25, self.steam_id);
        }
        if let Some(v) = &self.enter {
            wire::message(out, 26, &**v);
        }
        if let Some(v) = &self.exit {
            wire::message(out, 27, &**v);
        }
        if let Some(v) = &self.cycle {
            wire::message(out, 28, &**v);
        }
        for v in &self.classes {
            wire::string(out, 29, v);
        }
        for v in &self.sheets {
            wire::string(out, 30, v);
        }
        if self.free_cursor {
            wire::bool(out, 31, self.free_cursor);
        }
        if self.free_cursor_asks != 0 {
            wire::uint32(out, 33, self.free_cursor_asks);
        }
        for v in &self.cues {
            wire::message(out, 36, v);
        }
        if self.ability_bar_presses {
            wire::bool(out, 37, self.ability_bar_presses);
        }
        for v in &self.ability_display {
            wire::message(out, 38, v);
        }
        if let Some(v) = &self.clock {
            wire::message(out, 39, v);
        }
        if self.hide_in_chat {
            wire::bool(out, 40, self.hide_in_chat);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.id = r.string(kind)?,
                2 => message.kind = Kind::from_i32(r.int32(kind)?),
                3 => message.children.push(r.string(kind)?),
                4 => message.text = r.string(kind)?,
                5 => message.image = r.string(kind)?,
                6 => message.style = Style::decode(r.bytes(kind)?)?,
                7 => message.layout = r.string(kind)?,
                8 => message.data = r.string(kind)?,
                9 => r.repeated(kind, wire::VARINT, &mut message.hide_hud, |r, kind| Ok(HudPart::from_i32(r.int32(kind)?)))?,
                10 => message.route = r.string(kind)?,
                11 => message.hover = Some(Box::new(Style::decode(r.bytes(kind)?)?)),
                12 => message.tooltip = r.string(kind)?,
                32 => message.item = r.uint32(kind)?,
                34 => message.ability = r.uint32(kind)?,
                35 => message.ability_player = r.uint32(kind)?,
                13 => message.sound = r.string(kind)?,
                14 => message.hover_sound = r.string(kind)?,
                15 => message.disabled = r.bool(kind)?,
                16 => message.scaling = Scaling::from_i32(r.int32(kind)?),
                17 => message.hero = r.int32(kind)?,
                18 => message.hero_look = HeroLook::from_i32(r.int32(kind)?),
                19 => message.input = Some(NodeInput::TextEntry(TextEntry::decode(r.bytes(kind)?)?)),
                20 => message.input = Some(NodeInput::Slider(Slider::decode(r.bytes(kind)?)?)),
                21 => message.input = Some(NodeInput::Toggle(Toggle::decode(r.bytes(kind)?)?)),
                22 => message.input = Some(NodeInput::Dropdown(Dropdown::decode(r.bytes(kind)?)?)),
                23 => message.token = r.string(kind)?,
                24 => message.variables.push(NodeVariablesEntry::decode(r.bytes(kind)?)?),
                25 => message.steam_id = r.fixed64(kind)?,
                26 => message.enter = Some(Box::new(Style::decode(r.bytes(kind)?)?)),
                27 => message.exit = Some(Box::new(Style::decode(r.bytes(kind)?)?)),
                28 => message.cycle = Some(Box::new(Cycle::decode(r.bytes(kind)?)?)),
                29 => message.classes.push(r.string(kind)?),
                30 => message.sheets.push(r.string(kind)?),
                31 => message.free_cursor = r.bool(kind)?,
                33 => message.free_cursor_asks = r.uint32(kind)?,
                36 => message.cues.push(Cue::decode(r.bytes(kind)?)?),
                37 => message.ability_bar_presses = r.bool(kind)?,
                38 => message.ability_display.push(AbilityRow::decode(r.bytes(kind)?)?),
                39 => message.clock = Some(Clock::decode(r.bytes(kind)?)?),
                40 => message.hide_in_chat = r.bool(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct NodeVariablesEntry {
    pub key: String,
    pub value: String,
}

impl Message for NodeVariablesEntry {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.key.is_empty() {
            wire::string(out, 1, &self.key);
        }
        if !self.value.is_empty() {
            wire::string(out, 2, &self.value);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.key = r.string(kind)?,
                2 => message.value = r.string(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Clock is a time a label counts in the player's game.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Clock {
    /// seconds is the time the clock shows as the renderer first draws it.
    pub seconds: f64,
    /// up counts up from seconds; otherwise the clock counts down and stops at
    /// zero.
    pub up: bool,
    /// paused holds the clock at seconds.
    pub paused: bool,
    /// format writes the time.
    pub format: ClockFormat,
    /// run names one run of the clock. The renderer starts counting again from
    /// seconds when any of the clock's fields change, so a mod changes run to
    /// restart a clock at the same time, such as each round's opening. A
    /// renderer that first draws a running clock later, as after a reload,
    /// starts it from seconds.
    pub run: u32,
}

impl Message for Clock {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.seconds != 0.0 {
            wire::double(out, 1, self.seconds);
        }
        if self.up {
            wire::bool(out, 2, self.up);
        }
        if self.paused {
            wire::bool(out, 3, self.paused);
        }
        if self.format as i32 != 0 {
            wire::int32(out, 4, self.format as i32);
        }
        if self.run != 0 {
            wire::uint32(out, 5, self.run);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.seconds = r.double(kind)?,
                2 => message.up = r.bool(kind)?,
                3 => message.paused = r.bool(kind)?,
                4 => message.format = ClockFormat::from_i32(r.int32(kind)?),
                5 => message.run = r.uint32(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// AbilityRow is one player's abilities, as AbilityDisplay shows them.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct AbilityRow {
    /// player is the player's slot, whose hero the ability window reads its
    /// numbers from.
    pub player: Player,
    /// name is the player's name, which matches the player's Tab row.
    pub name: String,
    /// hero is the class name of the player's hero, such as hero_atlas, which
    /// matches a bot's row: a bot's row shows its hero's name in place of one.
    pub hero: String,
    /// own marks the row of the player whose screen this is; its abilities go on
    /// the ability bar as well.
    pub own: bool,
    /// abilities holds the four ability slots in order, at most four.
    pub abilities: Vec<ShownAbility>,
}

impl Message for AbilityRow {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.player.slot() != 0 {
            wire::uint32(out, 1, self.player.slot() as u32);
        }
        if !self.name.is_empty() {
            wire::string(out, 2, &self.name);
        }
        if !self.hero.is_empty() {
            wire::string(out, 3, &self.hero);
        }
        if self.own {
            wire::bool(out, 4, self.own);
        }
        for v in &self.abilities {
            wire::message(out, 5, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.player = Player::of(r.uint32(kind)? as i32),
                2 => message.name = r.string(kind)?,
                3 => message.hero = r.string(kind)?,
                4 => message.own = r.bool(kind)?,
                5 => message.abilities.push(ShownAbility::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// ShownAbility is the ability AbilityDisplay shows in one slot.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ShownAbility {
    /// ability is the ability's id, as Node.ability, whose window the game shows
    /// over it; zero shows none.
    pub ability: u32,
    /// image is the ability's picture, a path in the game's content as
    /// Node.image is. Without one, the slot shows the game's own ability.
    pub image: String,
    /// upgrades holds the bought tiers, as ability.upgrades does: bit 0 unlocks
    /// it and bits 1 to 3 are its upgrades.
    pub upgrades: u32,
}

impl Message for ShownAbility {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.ability != 0 {
            wire::uint32(out, 1, self.ability);
        }
        if !self.image.is_empty() {
            wire::string(out, 2, &self.image);
        }
        if self.upgrades != 0 {
            wire::uint32(out, 3, self.upgrades);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.ability = r.uint32(kind)?,
                2 => message.image = r.string(kind)?,
                3 => message.upgrades = r.uint32(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// Cue is one sound played to one player.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Cue {
    /// number orders the mod's cues for the player; a later cue has a higher
    /// number.
    pub number: u32,
    /// sound is the game's sound event, named as Node's sound is.
    pub sound: String,
    /// seconds cuts the sound after that long, keeping only its start; zero
    /// plays it out.
    pub seconds: f32,
    /// delay is how long the renderer waits before it plays the sound, in
    /// seconds, so a mod times a run of sounds, such as a wheel's ticks, in one
    /// draw. A cue whose mod leaves or clears its interface before then does
    /// not play.
    pub delay: f32,
}

impl Message for Cue {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.number != 0 {
            wire::uint32(out, 1, self.number);
        }
        if !self.sound.is_empty() {
            wire::string(out, 2, &self.sound);
        }
        if self.seconds != 0.0 {
            wire::float(out, 3, self.seconds);
        }
        if self.delay != 0.0 {
            wire::float(out, 4, self.delay);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.number = r.uint32(kind)?,
                2 => message.sound = r.string(kind)?,
                3 => message.seconds = r.float(kind)?,
                4 => message.delay = r.float(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// TextEntry is a box the player types a line of text into.
