/// Length is a size along one axis.
#[derive(Clone, Debug, PartialEq)]
pub enum Length {
    /// Pixels is a fixed size.
    Pixels(f32),
    /// Percent is a share of the parent's size, from 0 to 100.
    Percent(f32),
    /// FitChildren sizes the node to its children.
    FitChildren(bool),
    /// Fill shares the space left in the parent's flow by this weight.
    Fill(f32),
}

impl Length {
    /// encode appends the Length to out.
    pub fn encode(&self, out: &mut Vec<u8>) {
        match self {
            Self::Pixels(v) => wire::float(out, 1, *v),
            Self::Percent(v) => wire::float(out, 2, *v),
            Self::FitChildren(v) => wire::bool(out, 3, *v),
            Self::Fill(v) => wire::float(out, 4, *v),
        }
    }

    /// decode returns the Length in data, or None when data holds no case.
    pub fn decode(data: &[u8]) -> Result<Option<Self>, wire::Error> {
        let mut value = None;
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => value = Some(Self::Pixels(r.float(kind)?)),
                2 => value = Some(Self::Percent(r.float(kind)?)),
                3 => value = Some(Self::FitChildren(r.bool(kind)?)),
                4 => value = Some(Self::Fill(r.float(kind)?)),
                _ => r.skip(kind)?,
            }
        }
        Ok(value)
    }
}

