/// Change updates one player's tree. Reset clears the tree first; then each
/// node in set replaces the node with its id, and each id in removed drops
/// that node.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Change {
    /// reset clears the tree before the rest of the change applies.
    pub reset: bool,
    /// set holds the new or changed nodes.
    pub set: Vec<Node>,
    /// removed holds the ids of the nodes to drop.
    pub removed: Vec<String>,
    /// generation identifies the lifetime of the UI tree. Screen relays set it
    /// so a reset survives coalescing with the next redraw. Zero keeps the
    /// current generation, except an empty reset starts the next lifetime.
    /// Raw native events have this field cleared before the screen owner
    /// handles them; a mod cannot select its lifetime. Peer snapshots and
    /// deltas carry the screen owner's nonzero generation unchanged.
    pub generation: u64,
}

impl Message for Change {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.reset {
            wire::bool(out, 1, self.reset);
        }
        for v in &self.set {
            wire::message(out, 2, v);
        }
        for v in &self.removed {
            wire::string(out, 3, v);
        }
        if self.generation != 0 {
            wire::uint64(out, 4, self.generation);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.reset = r.bool(kind)?,
                2 => message.set.push(Node::decode(r.bytes(kind)?)?),
                3 => message.removed.push(r.string(kind)?),
                4 => message.generation = r.uint64(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// UiPressEvent reports a press on a button in a player's interface, or a
