pub struct UiInputEvent {
    /// player is the player who changed it.
    pub player: Player,
    /// node is the id of the input.
    pub node: String,
    /// value is the input's new value, in the kind its control holds.
    pub value: Option<UiInputEventValue>,
}

/// UiInputEventValue is the value of an UiInputEvent.
#[derive(Clone, Debug, PartialEq)]
pub enum UiInputEventValue {
    /// Text is a text entry's text.
    Text(String),
    /// Number is a slider's value.
    Number(f32),
    /// On is a toggle's state.
    On(bool),
    /// Choice is the index of a dropdown's chosen option.
    Choice(u32),
    /// Wheel is a wheel step over a slider that opted in to wheel events.
    Wheel(Wheel),
}

impl Message for UiInputEvent {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.player.slot() != 0 {
            wire::int32(out, 1, self.player.slot());
        }
        if !self.node.is_empty() {
            wire::string(out, 2, &self.node);
        }
        match &self.value {
            Some(UiInputEventValue::Text(v)) => wire::string(out, 3, v),
            Some(UiInputEventValue::Number(v)) => wire::float(out, 4, *v),
            Some(UiInputEventValue::On(v)) => wire::bool(out, 5, *v),
            Some(UiInputEventValue::Choice(v)) => wire::uint32(out, 6, *v),
            Some(UiInputEventValue::Wheel(v)) => wire::message(out, 7, v),
            None => {}
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.player = Player::of(r.int32(kind)?),
                2 => message.node = r.string(kind)?,
                3 => message.value = Some(UiInputEventValue::Text(r.string(kind)?)),
                4 => message.value = Some(UiInputEventValue::Number(r.float(kind)?)),
                5 => message.value = Some(UiInputEventValue::On(r.bool(kind)?)),
                6 => message.value = Some(UiInputEventValue::Choice(r.uint32(kind)?)),
                7 => message.value = Some(UiInputEventValue::Wheel(Wheel::decode(r.bytes(kind)?)?)),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

