/// StartEvent describes the server the mod starts in.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct StartEvent {
    /// args holds the arguments that follow -- on the host command line.
    pub args: Vec<String>,
    /// check_only is true when the host checks the mod without starting a game.
    /// The mod then hears no game events, and a call that needs the game fails;
    /// logging, the host's services, settings, metrics, files, interfaces and
    /// the reload hold still answer.
    pub check_only: bool,
    /// source holds an interpreted mod's entry, which the interpreter module
    /// evaluates during start. It is empty for a compiled mod.
    pub source: Vec<u8>,
}

impl Message for StartEvent {
    fn encode(&self, out: &mut Vec<u8>) {
        for v in &self.args {
            wire::string(out, 1, v);
        }
        if self.check_only {
            wire::bool(out, 2, self.check_only);
        }
        if !self.source.is_empty() {
            wire::bytes(out, 3, &self.source);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.args.push(r.string(kind)?),
                2 => message.check_only = r.bool(kind)?,
                3 => message.source = r.bytes(kind)?.to_vec(),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// StartResult declares which events the mod consumes.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct StartResult {
    /// frames asks for a Frame event every server frame.
    pub frames: bool,
    /// damage asks for a damage event before each hit.
    pub damage: bool,
    /// damaged asks for a damaged event after each hit.
    pub damaged: bool,
    /// chat asks for a chat event for each chat line.
    pub chat: bool,
    /// joins asks for a PlayerJoined event as each player the mod serves joins,
    /// PlayerAway and PlayerReturned events as they disconnect and come back,
    /// and a PlayerLeft event as each leaves.
    pub joins: bool,
    /// casts asks for an AbilityCast event after each ability the game
    /// executes.
    pub casts: bool,
    /// modifier_events asks for a ModifierFired event for each of the game's
    /// modifier events with these EModifierEvent names, such as
    /// MODIFIER_EVENT_ABILITY_CAST_STARTED or, without the prefix,
    /// ABILITY_CAST_STARTED. A name the running game lacks is logged and never
    /// fires.
    pub modifier_events: Vec<String>,
    /// kills asks for a Killed event after each hit that kills a hero or unit.
    pub kills: bool,
    /// heals asks for a Healed event after each heal.
    pub heals: bool,
    /// levels asks for a LevelChanged event as each hero reaches a new level.
    pub levels: bool,
    /// melees asks for a Melee event after each melee swing.
    pub melees: bool,
    /// parries asks for a Parried event after each parry that catches a swing.
    pub parries: bool,
    /// pings asks for a Ping event before each ping a player sends.
    pub pings: bool,
}

impl Message for StartResult {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.frames {
            wire::bool(out, 1, self.frames);
        }
        if self.damage {
            wire::bool(out, 2, self.damage);
        }
        if self.damaged {
            wire::bool(out, 3, self.damaged);
        }
        if self.chat {
            wire::bool(out, 4, self.chat);
        }
        if self.joins {
            wire::bool(out, 5, self.joins);
        }
        if self.casts {
            wire::bool(out, 6, self.casts);
        }
        for v in &self.modifier_events {
            wire::string(out, 7, v);
        }
        if self.kills {
            wire::bool(out, 8, self.kills);
        }
        if self.heals {
            wire::bool(out, 9, self.heals);
        }
        if self.levels {
            wire::bool(out, 10, self.levels);
        }
        if self.melees {
            wire::bool(out, 11, self.melees);
        }
        if self.parries {
            wire::bool(out, 12, self.parries);
        }
        if self.pings {
            wire::bool(out, 13, self.pings);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.frames = r.bool(kind)?,
                2 => message.damage = r.bool(kind)?,
                3 => message.damaged = r.bool(kind)?,
                4 => message.chat = r.bool(kind)?,
                5 => message.joins = r.bool(kind)?,
                6 => message.casts = r.bool(kind)?,
                7 => message.modifier_events.push(r.string(kind)?),
                8 => message.kills = r.bool(kind)?,
                9 => message.heals = r.bool(kind)?,
                10 => message.levels = r.bool(kind)?,
                11 => message.melees = r.bool(kind)?,
                12 => message.parries = r.bool(kind)?,
                13 => message.pings = r.bool(kind)?,
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

/// FrameEvent identifies one server frame.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct FrameEvent {
    /// tick is the server tick, or zero when the clock is unavailable.
    pub tick: u64,
    /// time_seconds is the game clock at this frame, in seconds.
    pub time_seconds: f64,
    /// movement holds one sample per watched, live hero when this frame starts a
    /// new tick, and is empty otherwise.
    pub movement: Vec<MovementSample>,
    /// interactions names the interaction kinds the host observes, sent with
    /// movement. A kind it lacks, such as on a game build whose completion it
    /// cannot find, is unknown rather than absent from the samples.
    pub interactions: Vec<InteractionKind>,
    /// controllers holds each watched player's controllers in every frame, with
    /// the presses and releases since the mod's previous frame.
    pub controllers: Vec<PlayerControllers>,
}

impl Message for FrameEvent {
    fn encode(&self, out: &mut Vec<u8>) {
        if self.tick != 0 {
            wire::uint64(out, 1, self.tick);
        }
        if self.time_seconds != 0.0 {
            wire::double(out, 2, self.time_seconds);
        }
        for v in &self.movement {
            wire::message(out, 3, v);
        }
        wire::packed(out, 4, &self.interactions, |out, v| wire::raw::int32(out, *v as i32));
        for v in &self.controllers {
            wire::message(out, 5, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.tick = r.uint64(kind)?,
                2 => message.time_seconds = r.double(kind)?,
                3 => message.movement.push(MovementSample::decode(r.bytes(kind)?)?),
                4 => r.repeated(kind, wire::VARINT, &mut message.interactions, |r, kind| Ok(InteractionKind::from_i32(r.int32(kind)?)))?,
                5 => message.controllers.push(PlayerControllers::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

