/// ScoreReport reports one score for one player, the request of the scores
/// service's asynchronous Report method, returning ScoreAccepted.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ScoreReport {
    /// board names a board the manifest declares.
    pub board: String,
    /// player is the player's server slot.
    pub player: Player,
    /// value is the score in the board's unit.
    pub value: i64,
    /// tiebreak ranks equal values, lower first, such as fewer deaths. Report
    /// a negated value to rank a higher one first. Equal tiebreaks rank the
    /// earlier score first.
    pub tiebreak: i64,
    /// partition names a value for each of the board's partitions.
    pub partition: Vec<ScoreReportPartitionEntry>,
    /// key identifies the round or run within this game, so a resent report
    /// counts once. Empty identifies the sole result for this player and board
    /// in the game. Use distinct keys for distinct rounds or runs.
    pub key: String,
    /// earned_at_unix_millis is when the player earned the score; zero takes the
    /// host's clock. It decides the windows the score falls in.
    pub earned_at_unix_millis: i64,
    /// evidence names what shows the run, such as a recording, for a host
    /// that keeps it.
    pub evidence: String,
    /// connection is the enrollment proof from Bind.
    pub connection: Option<ScoreConnection>,
    /// teammates are the scoring player's teammates on a team board, the
    /// board's team size less one; a board of single players takes none.
    pub teammates: Vec<Teammate>,
}

impl Message for ScoreReport {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.board.is_empty() {
            wire::string(out, 1, &self.board);
        }
        if self.player.slot() != 0 {
            wire::int32(out, 2, self.player.slot());
        }
        if self.value != 0 {
            wire::int64(out, 3, self.value);
        }
        if self.tiebreak != 0 {
            wire::int64(out, 4, self.tiebreak);
        }
        for v in &self.partition {
            wire::message(out, 5, v);
        }
        if !self.key.is_empty() {
            wire::string(out, 6, &self.key);
        }
        if self.earned_at_unix_millis != 0 {
            wire::int64(out, 7, self.earned_at_unix_millis);
        }
        if !self.evidence.is_empty() {
            wire::string(out, 8, &self.evidence);
        }
        if let Some(v) = &self.connection {
            wire::message(out, 9, v);
        }
        for v in &self.teammates {
            wire::message(out, 10, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.board = r.string(kind)?,
                2 => message.player = Player::of(r.int32(kind)?),
                3 => message.value = r.int64(kind)?,
                4 => message.tiebreak = r.int64(kind)?,
                5 => message.partition.push(ScoreReportPartitionEntry::decode(r.bytes(kind)?)?),
                6 => message.key = r.string(kind)?,
                7 => message.earned_at_unix_millis = r.int64(kind)?,
                8 => message.evidence = r.string(kind)?,
                9 => message.connection = Some(ScoreConnection::decode(r.bytes(kind)?)?),
                10 => message.teammates.push(Teammate::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

