/// BoardQuery reads a page of one board, the request of the scores service's
/// asynchronous Read method, returning BoardPage.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BoardQuery {
    /// board names a board the manifest declares.
    pub board: String,
    /// partition names a value for each of the board's partitions.
    pub partition: Vec<BoardQueryPartitionEntry>,
    /// window is one of the board's windows; unset reads all time.
    pub window: Window,
    /// offset skips that many rows from the top.
    pub offset: u32,
    /// limit bounds the rows; zero reads ten.
    pub limit: u32,
    /// player asks for this player's own row too, by server slot.
    pub player: Option<Player>,
    /// connection identifies the current viewer when player is set.
    pub connection: Option<ScoreConnection>,
    /// teammates name the viewer's teammates on a team board, so player's row
    /// is their team's; each is a player in the game now.
    pub teammates: Vec<Teammate>,
}

impl Message for BoardQuery {
    fn encode(&self, out: &mut Vec<u8>) {
        if !self.board.is_empty() {
            wire::string(out, 1, &self.board);
        }
        for v in &self.partition {
            wire::message(out, 2, v);
        }
        if self.window as i32 != 0 {
            wire::int32(out, 3, self.window as i32);
        }
        if self.offset != 0 {
            wire::uint32(out, 4, self.offset);
        }
        if self.limit != 0 {
            wire::uint32(out, 5, self.limit);
        }
        if let Some(v) = self.player {
            wire::int32(out, 6, v.slot());
        }
        if let Some(v) = &self.connection {
            wire::message(out, 7, v);
        }
        for v in &self.teammates {
            wire::message(out, 8, v);
        }
    }

    fn decode(data: &[u8]) -> Result<Self, wire::Error> {
        let mut message = Self::default();
        let mut r = wire::Reader::new(data);
        while let Some((number, kind)) = r.field()? {
            match number {
                1 => message.board = r.string(kind)?,
                2 => message.partition.push(BoardQueryPartitionEntry::decode(r.bytes(kind)?)?),
                3 => message.window = Window::from_i32(r.int32(kind)?),
                4 => message.offset = r.uint32(kind)?,
                5 => message.limit = r.uint32(kind)?,
                6 => message.player = Some(Player::of(r.int32(kind)?)),
                7 => message.connection = Some(ScoreConnection::decode(r.bytes(kind)?)?),
                8 => message.teammates.push(Teammate::decode(r.bytes(kind)?)?),
                _ => r.skip(kind)?,
            }
        }
        Ok(message)
    }
}

