    /// sound plays a game sound event, such as Damage.Send.Crit, on the
    /// player's hero, and returns its ID. It follows the hero as it moves.
    /// Volume and pitch scale the sound, and listeners limit who hears it.
    pub fn sound(self, sound: impl AsRef<str>, options: Option<&SoundOptions>) -> Option<u32> {
        host::call(
            "Sound",
            |out| {
                if self.slot() != 0 {
                    wire::int32(out, 1, self.slot());
                }
                if !sound.as_ref().is_empty() {
                    wire::string(out, 2, sound.as_ref());
                }
                if let Some(v) = options {
                    wire::message(out, 3, v);
                }
            },
            |r| {
                let mut result: u32 = Default::default();
                while let Some((number, kind)) = r.field()? {
                    match number {
                        1 => result = r.uint32(kind)?,
                        _ => r.skip(kind)?,
                    }
                }
                Ok(result)
            },
        )
    }

    /// restore_hero gives the player's live hero target over the next few
    /// seconds: the build first, then health, stamina and pose once it settles,
