/// call_service calls method of a service the host provides outside Modlock,
/// such as a game mode's match, and returns the service's answer. The
/// service defines the payload's encoding.
pub fn call_service(service: impl AsRef<str>, method: impl AsRef<str>, payload: &[u8]) -> Option<Vec<u8>> {
    host::call(
        "CallService",
        |out| {
            if !service.as_ref().is_empty() {
                wire::string(out, 1, service.as_ref());
            }
            if !method.as_ref().is_empty() {
                wire::string(out, 2, method.as_ref());
            }
            if !payload.is_empty() {
                wire::bytes(out, 3, payload);
            }
        },
        |r| {
            let mut result: Vec<u8> = Default::default();
            while let Some((number, kind)) = r.field()? {
                match number {
                    1 => result = r.bytes(kind)?.to_vec(),
                    _ => r.skip(kind)?,
                }
            }
            Ok(result)
        },
    )
}

/// start_service_call calls method of a service the host provides and
/// returns at once with a number; the answer arrives in a later frame as a
/// ServiceReplied event carrying that number. Every call ends once: with
/// the reply, the service's refusal, a timeout or no provider at all. A
/// service nobody provides is never asked. The host waits at most 30
/// seconds, or the call's shorter timeout, and drops the mod's waiting
/// calls when the mod stops or reloads. A service that answers at once
/// answers this way too, in the next frame.
pub fn start_service_call(service: impl AsRef<str>, method: impl AsRef<str>, payload: &[u8], timeout_milliseconds: u32) -> Option<u64> {
    host::call(
        "StartServiceCall",
        |out| {
            if !service.as_ref().is_empty() {
                wire::string(out, 1, service.as_ref());
            }
            if !method.as_ref().is_empty() {
                wire::string(out, 2, method.as_ref());
            }
            if !payload.is_empty() {
                wire::bytes(out, 3, payload);
            }
            if timeout_milliseconds != 0 {
                wire::uint32(out, 4, timeout_milliseconds);
            }
        },
        |r| {
            let mut result: u64 = Default::default();
            while let Some((number, kind)) = r.field()? {
                match number {
                    1 => result = r.uint64(kind)?,
                    _ => r.skip(kind)?,
                }
            }
            Ok(result)
        },
    )
}

